def transform(grid):
    """Extract the 8-connected motif with adjacent 3-cell rows."""
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0
                                and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            q.append((ny, nx))
            objects.append(cells)

    def has_adjacent_three_rows(cells):
        row_counts = {}
        for r, c in cells:
            row_counts[r] = row_counts.get(r, 0) + 1
        rows = sorted(row_counts)
        return any(row_counts[a] == row_counts[b] == 3 and b == a + 1
                   for a, b in zip(rows, rows[1:]))

    selected = [obj for obj in objects if has_adjacent_three_rows(obj)]
    if len(selected) != 1:
        raise ValueError(f"Expected one marked motif, found {len(selected)}")
    cells = selected[0]
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    return [[grid[r][c] for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]
